from fastapi import FastAPI, Query, Header, Cookie
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field

app = FastAPI()

class QueryModel(BaseModel):
    q: str = Field(..., alias="query_param")

@app.get("/query")
async def read_query(params: QueryModel = Query()):
    return params

class HeaderModel(BaseModel):
    user_agent: str = Field(..., alias="User-Agent")

@app.get("/header")
async def read_header(params: HeaderModel = Header()):
    return params

client = TestClient(app)

def test_query_alias():
    # Test 1: Value extracted by alias, should be put into values with alias key
    # If it's put with field.name, validation fails.
    response = client.get("/query", params={"query_param": "hello"})
    print(f"Query alias response: {response.status_code}, {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"q": "hello"}

def test_query_name_error():
    # Test 2: Pass value by name, should get validation error and 'q' should be in input
    response = client.get("/query", params={"q": "hello"})
    print(f"Query name response: {response.status_code}, {response.json()}")
    assert response.status_code == 422
    # The error should contain 'q' in the input
    errors = response.json()["detail"]
    print(f"Errors: {errors}")

def test_header_alias():
    # Test 1: Value extracted by alias
    response = client.get("/header", headers={"User-Agent": "my-agent"})
    print(f"Header alias response: {response.status_code}, {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"user_agent": "my-agent"}

def test_header_name_error():
    # Test 2: Pass value by name (user_agent), should get validation error and 'user_agent' should be in input
    response = client.get("/header", headers={"user_agent": "my-agent"})
    print(f"Header name response: {response.status_code}, {response.json()}")
    assert response.status_code == 422
    errors = response.json()["detail"]
    print(f"Errors: {errors}")

if __name__ == "__main__":
    try:
        test_query_alias()
    except Exception as e:
        print(f"test_query_alias failed: {e}")
    try:
        test_query_name_error()
    except Exception as e:
        print(f"test_query_name_error failed: {e}")
    try:
        test_header_alias()
    except Exception as e:
        print(f"test_header_alias failed: {e}")
    try:
        test_header_name_error()
    except Exception as e:
        print(f"test_header_name_error failed: {e}")
